"use strict";(()=>{chrome.runtime.onInstalled.addListener(()=>{chrome.sidePanel.setPanelBehavior({openPanelOnActionClick:!0}).then(()=>{console.log("[Career Agents Background] Side panel activated on action click.")}).catch(e=>{console.error("[Career Agents Background] Error setting panel behavior:",e)})});chrome.runtime.onMessage.addListener((e,t,r)=>{if(e.type==="PING_BACKGROUND")r({type:"PING_RESPONSE",payload:{active:!0}});else if(e.type==="OPEN_SIDEPANEL"&&t.tab&&t.tab.id)return chrome.sidePanel.open({tabId:t.tab.id}).then(()=>r({success:!0})).catch(a=>r({success:!1,error:a.message})),!0;return!0});})();
